        == offsetof(hybrid_state_v1, fcsr) + sizeof(uint64_t));
  CHECK(offsetof(hybrid_state_v1, mmisc_ctl)
        == offsetof(hybrid_state_v1, mcache_ctl) + sizeof(uint64_t));
}

TEST_CASE("v3: struct hybrid_andes_csr follows mmisc_ctl; v4: hybrid_m_ext_csr "
          "follows it, before reserved")
{
  CHECK(HYBRID_FLAG_ANDES == (1u << 3));
  CHECK(HYBRID_FLAG_M_EXT == (1u << 4));
  CHECK(offsetof(hybrid_state_v1, andes)
        == offsetof(hybrid_state_v1, mmisc_ctl) + sizeof(uint64_t));
  CHECK(offsetof(hybrid_state_v1, m_ext)
        == offsetof(hybrid_state_v1, andes) + sizeof(hybrid_andes_csr));
  CHECK(offsetof(hybrid_state_v1, reserved)
        == offsetof(hybrid_state_v1, m_ext) + sizeof(hybrid_m_ext_csr));
