  s.andes.jvt = 0x017;        // Zcmt jump table
  s.andes.ucode = 1;          // DSP overflow flag
  s.andes.mxstatus = 0x40;    // Andes mstatus companion
  CHECK(s.andes.uitb + s.andes.jvt + s.andes.ucode + s.andes.mxstatus
        == 0x800 + 0x017 + 1 + 0x40);
}

